initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let demandPredictions = [];
  let currentStock = [];

  // 店舗データの初期化
  function initStores() {
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable) {
      stores = storeTable.records || [];
      const storeSelect = container.querySelector('#store-select');
      stores.forEach(store => {
        const option = document.createElement('option');
        option.value = store.id;
        option.textContent = `${store.店舗名} (${store.店舗コード})`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 商品テーブル再描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; padding: 2rem; color: var(--text-muted);">該当する商品がありません</td></tr>';
      updateSummary([]);
      return;
    }

    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id) || {};
      const stock = currentStock.find(s => s.商品ID === product.id) || {};
      const predictedDemand = prediction.予測数量 || 0;
      const stockAmount = stock.在庫数量 || 0;
      const recommendedOrder = Math.max(0, predictedDemand - stockAmount);

      return `
        <tr data-id="${product.id}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.id}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${getCategoryName(product.商品カテゴリID)}</td>
          <td style="text-align: right;">${predictedDemand.toLocaleString()}</td>
          <td style="text-align: right;">${stockAmount.toLocaleString()}</td>
          <td style="text-align: right; color: var(--primary); font-weight: bold;">${recommendedOrder.toLocaleString()}</td>
          <td>
            <input type="number" class="input order-quantity" data-id="${product.id}" 
                   value="${recommendedOrder}" min="0" style="width: 80px;">
            <button class="action-btn secondary adjust-btn" data-id="${product.id}" data-action="use-recommended">推奨</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-id="${product.id}" 
                   placeholder="発注理由" style="width: 150px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-id="${product.id}">発注</button>
          </td>
        </tr>
      `;
    }).join('');

    updateSummary(products);
  }

  // カテゴリ名取得
  function getCategoryName(categoryId) {
    // 簡易的なカテゴリマッピング
    const categories = {
      '1': '食品',
      '2': '日用品', 
      '3': '衣料品',
      '4': '家電'
    };
    return categories[categoryId] || '未分類';
  }

  // サマリー更新
  function updateSummary(products) {
    let totalPrediction = 0;
    let totalStock = 0;
    let totalRecommended = 0;

    products.forEach(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id) || {};
      const stock = currentStock.find(s => s.商品ID === product.id) || {};
      const predictedDemand = prediction.予測数量 || 0;
      const stockAmount = stock.在庫数量 || 0;

      totalPrediction += predictedDemand;
      totalStock += stockAmount;
      totalRecommended += Math.max(0, predictedDemand - stockAmount);
    });

    container.querySelector('#total-prediction').textContent = totalPrediction.toLocaleString();
    container.querySelector('#total-stock').textContent = totalStock.toLocaleString();
    container.querySelector('#total-recommended').textContent = totalRecommended.toLocaleString();
  }

  // 商品データ読み込み
  async function loadProducts() {
    try {
      const productTable = tables.findIndex(t => t.tableName === '商品マスタ');
      if (productTable >= 0) {
        const products = await window.aivicApi.list(productTable);
        if (products) {
          currentProducts = products;
          return products;
        }
      }
      return tables.find(t => t.tableName === '商品マスタ')?.records || [];
    } catch (error) {
      console.error('商品データの読み込みに失敗:', error);
      return [];
    }
  }

  // 需要予測データ読み込み
  async function loadDemandPredictions() {
    try {
      const predictionTable = tables.findIndex(t => t.tableName === '需要予測結果');
      if (predictionTable >= 0) {
        const predictions = await window.aivicApi.list(predictionTable);
        if (predictions) {
          demandPredictions = predictions;
        }
      }
    } catch (error) {
      console.error('需要予測データの読み込みに失敗:', error);
    }
  }

  // 在庫データ読み込み（売上実績から推定）
  async function loadCurrentStock() {
    try {
      // 簡易的な在庫計算（実際のシステムでは在庫マスタから取得）
      currentStock = currentProducts.map(product => ({
        商品ID: product.id,
        在庫数量: Math.floor(Math.random() * 100) + 10 // ダミーデータ
      }));
    } catch (error) {
      console.error('在庫データの読み込みに失敗:', error);
    }
  }

  // 検索・フィルタリング
  function filterProducts() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const searchText = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      renderProducts([]);
      return;
    }

    // 日付バリデーション
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      alert('終了日は開始日以降の日付を入力してください');
      return;
    }

    let filtered = currentProducts.filter(product => {
      // カテゴリフィルタ
      if (category && getCategoryName(product.商品カテゴリID) !== category) {
        return false;
      }

      // 商品名検索
      if (searchText && !product.商品名?.toLowerCase().includes(searchText)) {
        return false;
      }

      return true;
    });

    renderProducts(filtered);
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    if (!quantity || quantity <= 0) {
      alert('発注量は正の数値を入力してください');
      return false;
    }

    if (isNaN(quantity)) {
      alert('発注量は数値で入力してください');
      return false;
    }

    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    const product = currentProducts.find(p => p.id === productId);
    if (!product) {
      alert('商品が見つかりません');
      return false;
    }

    try {
      const orderTable = tables.findIndex(t => t.tableName === '発注データ');
      if (orderTable >= 0) {
        const orderData = {
          店舗ID: storeId,
          商品ID: productId,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: parseInt(quantity),
          発注単価: product.単価 || 0,
          発注金額: parseInt(quantity) * (product.単価 || 0),
          発注方法: reason ? 'AI推奨修正' : 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID || '',
          発注理由: reason || 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        const result = await window.aivicApi.save(orderTable, orderData);
        if (result) {
          alert('発注が完了しました');
          return true;
        }
      }
      alert('発注処理に失敗しました');
      return false;
    } catch (error) {
      console.error('発注処理エラー:', error);
      alert('発注処理中にエラーが発生しました');
      return false;
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const headers = ['商品コード', '商品名', 'カテゴリ', '予測需要量', '現在在庫数', '推奨発注量'];
    const rows = currentProducts.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id) || {};
      const stock = currentStock.find(s => s.商品ID === product.id) || {};
      const predictedDemand = prediction.予測数量 || 0;
      const stockAmount = stock.在庫数量 || 0;
      const recommendedOrder = Math.max(0, predictedDemand - stockAmount);

      return [
        product.商品コード || '',
        product.商品名 || '',
        getCategoryName(product.商品カテゴリID),
        predictedDemand,
        stockAmount,
        recommendedOrder
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  async function initialize() {
    initStores();
    await loadProducts();
    await loadDemandPredictions();
    await loadCurrentStock();
  }

  // イベントリスナー
  container.querySelector('#btn-search').addEventListener('click', filterProducts);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#store-select').value = '';
    container.querySelector('#category-select').value = '';
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#product-search').value = '';
    renderProducts([]);
  });

  container.querySelector('#store-select').addEventListener('change', filterProducts);

  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 商品行のイベント処理
  container.addEventListener('click', async (e) => {
    // 推奨発注量適用
    if (e.target.classList.contains('adjust-btn')) {
      const productId = e.target.dataset.id;
      const row = e.target.closest('tr');
      const recommendedCell = row.cells[6];
      const recommendedValue = recommendedCell.textContent.replace(/,/g, '');
      const quantityInput = row.querySelector('.order-quantity');
      quantityInput.value = recommendedValue;
    }

    // 個別発注
    if (e.target.classList.contains('order-btn')) {
      const productId = e.target.dataset.id;
      const row = e.target.closest('tr');
      const quantity = row.querySelector('.order-quantity').value;
      const reason = row.querySelector('.order-reason').value;

      if (await processOrder(productId, quantity, reason)) {
        row.querySelector('.order-quantity').value = '';
        row.querySelector('.order-reason').value = '';
      }
    }
  });

  // 一括発注
  container.querySelector('#btn-bulk-order').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.product-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    let successCount = 0;
    for (const checkbox of checkedBoxes) {
      const productId = checkbox.dataset.id;
      const row = checkbox.closest('tr');
      const quantity = row.querySelector('.order-quantity').value;
      const reason = row.querySelector('.order-reason').value;

      if (await processOrder(productId, quantity, reason)) {
        successCount++;
        checkbox.checked = false;
        row.querySelector('.order-quantity').value = '';
        row.querySelector('.order-reason').value = '';
      }
    }

    alert(`${successCount}件の発注が完了しました`);
    container.querySelector('#select-all').checked = false;
  });

  // 初期化実行
  initialize();
}
